  const openEdit = (b: Brand) => { setEditId(b.id!); setEditForm({ ...b }); setEditErrors({}); setShowEditModal(true) }
  const handleUpdate = async () => { if(!editForm||editId===null) return; const errs:Record<string,string>={}; if(!editForm.name.trim()) errs.name="Required"; setEditErrors(errs); if(Object.keys(errs).length) return; await update(editId,{...editForm,name:editForm.name.trim()}); setShowEditModal(false); setEditId(null); setEditForm(null) }
