      <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="bg-gray-50 border-b"><th className="text-left px-4 py-3 font-semibold text-gray-600 text-xs uppercase">#</th><th className="text-left px-4 py-3 font-semibold text-gray-600 text-xs uppercase">Brand</th><th className="text-left px-4 py-3 font-semibold text-gray-600 text-xs uppercase">Description</th><th className="text-right px-4 py-3 font-semibold text-gray-600 text-xs uppercase">Action</th></tr></thead><tbody>{filtered.length===0?<tr><td colSpan={4} className="text-center py-8 text-gray-400">No brands found</td></tr>:filtered.map((b,idx)=><tr key={b.id} className={`border-b hover:bg-gray-50 ${idx%2?"bg-gray-50/50":""}`}><td className="px-4 py-3 text-gray-600">{idx+1}</td><td className="px-4 py-3 font-medium">{b.name}</td><td className="px-4 py-3 text-gray-600">{b.description||"-"}</td><td className="px-4 py-3 text-right"><div className="flex justify-end gap-1"><button onClick={()=>openEdit(b)} className="p-1.5 text-amber-600 hover:bg-amber-50 rounded-lg"><Pencil className="h-4 w-4"/></button><button onClick={()=>{setDeleteId(b.id!);setShowDeleteModal(true)}} className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 className="h-4 w-4"/></button></div></td></tr>)}</tbody></table></div>
