      {showDeleteModal && <div className="fixed inset-0 z-50 flex items-center justify-center p-4"><div className="absolute inset-0 bg-black/50" onClick={()=>setShowDeleteModal(false)}/><div className="relative bg-white rounded-xl shadow-2xl w-full max-w-md z-10"><div className="flex items-center justify-between px-6 py-4 border-b"><h3 className="font-semibold">Confirm Delete</h3><button onClick={()=>setShowDeleteModal(false)}><X className="h-5 w-5 text-gray-400"/></button></div><div className="p-6"><p className="text-sm text-gray-600">Are you sure you want to delete this brand?</p>{deleteId&&<p className="text-sm font-semibold mt-1">{brands.find((b)=>b.id===deleteId)?.name}</p>}</div><div className="px-6 py-4 border-t flex justify-end gap-2"><button onClick={()=>setShowDeleteModal(false)} className="px-4 py-2 text-sm border rounded-lg">Cancel</button><button onClick={confirmDelete} className="px-4 py-2 bg-red-600 text-white text-sm rounded-lg">Delete</button></div></div></div>}
