function MastersInner() {
  const searchParams = useSearchParams()
  const initialTab = (searchParams.get("tab") as TabKey) || "categories"
  const validTabs: TabKey[] = ["categories","brands","units","vendors","variations","stores","coupons"]
  const [active, setActive] = useState<TabKey>(validTabs.includes(initialTab) ? initialTab : "categories")
  useEffect(() => {
    const t = searchParams.get("tab") as TabKey
    if (t && validTabs.includes(t)) setActive(t)
  }, [searchParams])

  return (
    <div className="space-y-6">
      <div className="relative overflow-hidden rounded-xl bg-gradient-to-r from-[var(--primary)] to-[var(--primary)]/80 px-6 py-4 shadow-sm">
        <div className="relative z-10">
          <h2 className="text-xl font-bold text-white">Inventory Masters</h2>
          <p className="text-sm text-white/80 mt-1">Students Inventory / Masters</p>
        </div>
      </div>

      <div className="rounded-xl border border-gray-200 bg-white shadow-sm">
        <div className="flex items-center gap-1 px-2 pt-2 border-b border-gray-200 overflow-x-auto">
          {tabs.map((t) => (
            <button
              key={t.key}
              onClick={() => setActive(t.key)}
              className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 whitespace-nowrap transition-colors ${active === t.key ? "border-[var(--primary)] text-[var(--primary)]" : "border-transparent text-gray-500 hover:text-gray-700"}`}
            >
              <t.icon className="h-4 w-4" />{t.label}
            </button>
          ))}
        </div>

        <div>
          {active === "categories" && <CategoriesTab />}
          {active === "brands" && <BrandsTab />}
          {active === "units" && <UnitsTab />}
          {active === "vendors" && <VendorsTab />}
          {active === "variations" && <VariationsTab />}
          {active === "stores" && <StoresTab />}
          {active === "coupons" && <CouponsTab />}
        </div>
      </div>
    </div>
  )
}

export default function MastersPage() {
  return (
    <Suspense fallback={<div className="flex items-center justify-center py-24 text-gray-500">Loading masters...</div>}>
      <MastersInner />
    </Suspense>
  )
}
